#include <cstdio>
#include <cstdlib>
#include "engine/gameplay/force_spec_lifecycle.hpp"
namespace {unsigned checks=0;void check(bool b,const char* why){++checks;if(!b){std::fprintf(stderr,"spec lifecycle: %s\n",why);std::abort();}}}
int main(){using namespace gf;ScreenFade fade;check(!fade.request(0,0,ScreenFadeDirection::Cover),"zero duration refuses");check(fade.request(0x123456ff,16,ScreenFadeDirection::Reveal),"reveal");for(unsigned i=1;i<=16;++i){fade.advance();check(fade.remaining()==16-i&&fade.draw()==(i<16),"decrement before draw");check(fade.colour()==(0x12345600u|(i<16?255*(16-i)/16:15)),"reveal alpha terminal retained");}check(fade.request(0,16,ScreenFadeDirection::Cover),"cover");for(unsigned i=1;i<=16;++i){fade.advance();check(fade.draw()&&fade.colour()==255*i/16,"cover alpha");}fade.advance();check(fade.draw()&&fade.colour()==255,"opaque holds");fade.clear();fade.advance();check(!fade.draw()&&!fade.remaining(),"clear after scene");
    ForceSpecLifecycleProfile p;p.bank_hash=1;p.weights.fill(1);p.total=64;p.start_z=-200;p.distance=200;p.fade_callbacks=16;p.release_callbacks=4;p.slide_callbacks=16;ForceSpecLifecycle life;ForceSpecLifecycleEvents e;check(life.open(p,7,ForceSpecPage::Statistics),"open");for(unsigned i=0;i<5;++i)check(life.step(false,0x203,&e)&&!e.show&&!life.visible()&&!life.fade().draw(),"real resource wait does not synthesize readiness");check(life.step(true,0x203,&e)&&e.show&&life.phase()==ForceSpecPhase::Opening&&life.actor_z()==0&&life.fade().remaining()==15,"show callback preserves source initial z0");for(unsigned i=1;i<=16;++i)check(life.step(true,0x203,&e)&&life.phase()==ForceSpecPhase::Opening&&life.slide_index()==i*4&&life.actor_z()==-200+12.5f*i&&!e.sound,"four weights; input gated");check(life.step(true,0x203,&e)&&life.phase()==ForceSpecPhase::RevealWait,"completion callback after all weights");check(life.step(true,0x203,&e)&&life.phase()==ForceSpecPhase::Active&&!e.sound,"active transition consumes input");check(life.step(true,3,&e)&&e.page_changed&&life.navigation().page()==ForceSpecPage::Moves,"right before left");check(life.step(true,0x203,&e)&&e.sound==123&&!e.page_changed&&life.phase()==ForceSpecPhase::CloseStart&&!life.fade().draw(),"B close has separate fade-start callback");check(life.step(true,0,&e)&&life.phase()==ForceSpecPhase::CoverWait&&life.fade().remaining()==15,"close fade starts");for(unsigned i=0;i<15;++i)check(life.step(true,0x203,&e)&&!e.retire,"observe prior counter");check(life.step(true,0,&e)&&e.retire&&life.release_remaining()==4&&!life.visible(),"retire on next callback after opaque");for(unsigned i=0;i<4;++i)check(life.step(true,0,&e)&&e.release==(i==3),"four release callbacks");check(life.phase()==ForceSpecPhase::Done&&!life.fade().draw()&&!life.step(true,0,&e)&&!e.release,"done cannot replay");std::printf("spec lifecycle/fade: %u checks PASS\n",checks);}
